largest-substring-between-two-equal-char:
class Solution:
    def maxLengthBetweenEqualCharacters(self, s: str) -> int:
        first = {}
        best = -1
        for i, c in enumerate(s):
            if c in first:
                if i - first[c] - 1 > best:
                    best = i - first[c] - 1
            else:
                first[c] = i
        return best

largest-triangle-area:
class Solution:
    def largestTriangleArea(self, points: list[list[int]]) -> float:
        best = 0.0
        n = len(points)
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    x1, y1 = points[i]
                    x2, y2 = points[j]
                    x3, y3 = points[k]
                    area = abs((x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1)) / 2.0
                    if area > best:
                        best = area
        return best

latest-time-by-replacing-hidden-digits:
class Solution:
    def maximumTime(self, time: str) -> str:
        t = list(time)
        if t[0] == '?':
            if t[1] != '?' and int(t[1]) > 3:
                t[0] = '1'
            else:
                t[0] = '2'
        if t[1] == '?':
            if t[0] == '2':
                t[1] = '3'
            else:
                t[1] = '9'
        if t[3] == '?':
            t[3] = '5'
        if t[4] == '?':
            t[4] = '9'
        return ''.join(t)

long-pressed-name:
class Solution:
    def isLongPressedName(self, name: str, typed: str) -> bool:
        i = 0
        for j, c in enumerate(typed):
            if i < len(name) and c == name[i]:
                i += 1
            elif j == 0 or c != typed[j - 1]:
                return False
        return i == len(name)

longest-alternating-subarray:
class Solution:
    def alternatingSubarray(self, nums: list[int]) -> int:
        best = -1
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if (j - i) % 2 == 1:
                    want = 1
                else:
                    want = -1
                if nums[j] - nums[j - 1] != want:
                    break
                ln = j - i + 1
                if ln > best:
                    best = ln
        return best

longest-even-odd-subarray-with-threshold:
class Solution:
    def longestAlternatingSubarray(self, nums: list[int], threshold: int) -> int:
        best = 0
        n = len(nums)
        for l in range(n):
            if nums[l] % 2 != 0 or nums[l] > threshold:
                continue
            r = l
            while r + 1 < n and nums[r + 1] <= threshold and nums[r + 1] % 2 != nums[r] % 2:
                r += 1
            ln = r - l + 1
            if ln > best:
                best = ln
        return best

lucky-numbers-in-a-matrix:
class Solution:
    def luckyNumbers(self, matrix: list[list[int]]) -> list[int]:
        rowmin = [min(r) for r in matrix]
        colmax = [max(c) for c in zip(*matrix)]
        out = []
        for i, r in enumerate(matrix):
            for j, v in enumerate(r):
                if v == rowmin[i] and v == colmax[j]:
                    out.append(v)
        return out

majority-element:
class Solution:
    def majorityElement(self, nums: list[int]) -> int:
        cand = nums[0]
        count = 0
        for v in nums:
            if count == 0:
                cand = v
                count = 1
            elif v == cand:
                count += 1
            else:
                count -= 1
        return cand
